display.text:
#!/usr/bin/env bash
set -Eeuo pipefail
IFS=$'\n\t'

upper() {
  printf '%s\n' "${1^^}"
}

input.newString:
upper() {
  printf '%s\n' "${1^^}"
}

reverse() {
  local s=${1-} out='' i
  for ((i = ${#s} - 1; i >= 0; i--)); do
    out+=${s:i:1}
  done
  printf '%s\n' "$out"
}

